const $ = s => document.querySelector(s);
const motionAllowed = () => window.matclubSettings ? window.matclubSettings.motionAllowed() : !window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {grade:window.matclubSettings?.value.defaultGrade||7,subject:'algebra',topic:null,level:-1,strongOnly:false,view:'catalog',query:'',domain:readLocal('matclub-domain','math')==='physics'?'physics':'math',section:'all'};
function readLocal(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v===null?fallback:v}catch{return fallback}}
let saved=readLocal('matclub-saved',[]),solved=readLocal('matclub-solved',[]),workbook=readLocal('matclub-workbook',{});
if(!Array.isArray(saved))saved=[];if(!Array.isArray(solved))solved=[];if(!workbook||typeof workbook!=='object'||Array.isArray(workbook))workbook={};
saved=saved.filter(id=>tasks.some(t=>t.id===id));solved=solved.filter(id=>tasks.some(t=>t.id===id));
function storeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Не удалось сохранить: в браузере закончилось место или хранилище недоступно.');return false}}
function persist(){storeLocal('matclub-saved',saved);storeLocal('matclub-solved',solved)}
function saveWork(){if(storeLocal('matclub-workbook',workbook)&&$('#saveStatus'))$('#saveStatus').textContent='Сохранено в браузере'}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
const taskSearch=new Map(tasks.map(t=>[t.id,`${t.title} ${t.question} ${t.topicName} ${levels[t.level]}`.toLowerCase()]));
function matches(t){return !state.query||taskSearch.get(t.id).includes(state.query)}
function domainTasks(){return tasks.filter(t=>t.domain===state.domain)}
function subjectMatches(t){return t.domain===state.domain&&(state.view==='favorites'||state.domain==='physics'?(state.view==='favorites'||state.section==='all'||physicsTopics.find(p=>p.key===`${t.grade}-${t.topic}`)?.section===state.section):(state.grade===6||t.subject===state.subject))}
function pool(ignoreLevel=false){return tasks.filter(t=>(state.view==='favorites'?saved.includes(t.id):t.grade===state.grade)&&(state.topic===null||t.topic===state.topic)&&(ignoreLevel||state.level<0||t.level===state.level)&&subjectMatches(t)&&matches(t)&&(!state.strongOnly||t.challenge))}
function card(t,index){return `<article class="task-card" style="--order:${Math.min(index,8)}"><span class="task-num">${String(index+1).padStart(2,'0')}</span><div class="task-info"><h3>${t.title} ${solved.includes(t.id)?'<span class="solved-label">✓</span>':''} ${t.isNew?'<span class="new-tag">НОВАЯ</span>':''}</h3><p>${t.question}</p><span class="task-caption">${t.challenge?'<b class="challenge-label">РАССУЖДЕНИЕ</b> · ':''}${t.grade} класс · ${t.topicName}</span></div><span class="task-meta"><i class="dot ${['green','amber','purple'][t.level]}"></i>${levels[t.level]}</span><button class="bookmark ${saved.includes(t.id)?'saved':''}" data-save="${t.id}" aria-label="${saved.includes(t.id)?'Удалить из избранного':'Добавить в избранное'}" aria-pressed="${saved.includes(t.id)}">${saved.includes(t.id)?'◆':'♧'}</button><button class="solve" data-open="${t.id}">${solved.includes(t.id)?'Повторить':'Решить'} ↗</button></article>`}
let lastCatalogKey='',visibleTaskLimit=24;
function render(){
if(state.domain==='physics'&&state.grade<7)state.grade=7;const isPhysics=state.domain==='physics';const domainLabel=isPhysics?'Физика':'Математика';document.documentElement.dataset.domain=state.domain;document.querySelectorAll('button[data-domain]').forEach(b=>{b.classList.toggle('selected',b.dataset.domain===state.domain);b.setAttribute('aria-pressed',String(b.dataset.domain===state.domain))});$('.hero h1').innerHTML=isPhysics?'От наблюдения<br>к <em>открытию.</em>':'Сложные задачи.<br>Ясные <em>идеи.</em>';$('.hero-copy>.eyebrow').innerHTML=isPhysics?'<span></span> МЕХАНИКА · ЭЛЕКТРИЧЕСТВО · ОПТИКА':'<span></span> АЛГЕБРА · ГЕОМЕТРИЯ · ОТКРЫТИЯ';$('.hero-copy>p').textContent=isPhysics?'От наблюдения к закону. Разбирай явления, выбирай модель и проверяй расчёты.':'От первого вопроса до красивого решения. Изучай, строй графики и проверяй свои идеи.';$('.hero-foot').textContent=isPhysics?`7–11 классы · 40 тем · ${tasks.filter(t=>t.domain==='physics').length} задач`:`6–11 классы · 57 тем · ${tasks.filter(t=>t.domain==='math').length} задач`;$('.curriculum-note').textContent=isPhysics?'Физика 7–11 классов: основные направления российской школьной программы. Порядок тем зависит от учебника. В каждой задаче указаны необходимые константы и допущения.':'6 класс — математика; с 7 класса — алгебра и геометрия. Ориентир: основные темы российской школы. Вероятность и статистика пока входят в алгебру.';
const isGraph=state.view==='graphs';document.documentElement.dataset.page=state.view;$('#graphSection').hidden=!isGraph;$('.study-ribbon').hidden=isGraph||state.view!=='catalog';$('#catalog').hidden=isGraph;$('.hero').hidden=isGraph||state.view!=='catalog';$('.discovery').hidden=isGraph||state.view!=='catalog';$('.search').hidden=isGraph;$('.curriculum-note').hidden=state.view!=='catalog';if(isGraph){$('#breadcrumb').textContent='Графики функций';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='graphs'));window.matclubPlotter?.refresh();return}
const catalogKey=[state.domain,state.grade,state.section,state.subject,state.level,state.topic,state.view,state.strongOnly].join('|');const navigationChanged=catalogKey!==lastCatalogKey;if(navigationChanged)visibleTaskLimit=24;lastCatalogKey=catalogKey;
$('#favcount').textContent=domainTasks().filter(t=>saved.includes(t.id)).length;
document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
$('#breadcrumb').textContent=domainLabel+' / '+({catalog:'Каталог тем',favorites:'Избранное',progress:'Мой прогресс'}[state.view]);
$('#sectionTitle').textContent={catalog:'Что изучим сегодня?',favorites:'Красивые задачи стоит сохранить',progress:'Каждое решение — шаг вперёд'}[state.view];
$('#catalogNote').textContent=state.view==='catalog'?'Сначала разберись в идее, потом проверь себя':state.view==='favorites'?'Избранные задачи всех классов':`Твой путь · ${domainLabel.toLowerCase()}`;
$('.grade-row').hidden=state.view!=='catalog';$('#catalog-content').hidden=state.view==='progress';$('#progress-content').hidden=state.view!=='progress';$('.topics-head').hidden=state.view!=='catalog';$('#topics').hidden=state.view!=='catalog';
$('#grades').innerHTML=(isPhysics?physicsGrades:supportedGrades).map(g=>`<button data-grade="${g}" class="${state.grade===g?'selected':''}" aria-pressed="${state.grade===g}">${g}</button>`).join('');
$('#subjectTabs').hidden=isPhysics||state.grade===6||state.view!=='catalog';document.querySelectorAll('[data-subject]').forEach(b=>{b.classList.toggle('selected',b.dataset.subject===state.subject);b.setAttribute('aria-pressed',String(b.dataset.subject===state.subject))});$('#gradeLabel').textContent=`${state.grade} класса`;
$('#physicsFilter').hidden=!isPhysics||state.view!=='catalog';const sections=[...new Set(physicsTopics.filter(p=>p.grade===state.grade).map(p=>p.section))];$('#physicsSection').innerHTML='<option value="all">Все направления</option>'+sections.map(n=>`<option ${n===state.section?'selected':''}>${esc(n)}</option>`).join('');
const topics=curriculum[state.grade];
const visibleTopics=topics.map((t,i)=>({t,i})).filter(({i})=>isPhysics?(topicSubjects[`${state.grade}-${i}`]==='physics'&&(state.section==='all'||physicsTopics.find(p=>p.key===`${state.grade}-${i}`)?.section===state.section)):(topicSubjects[`${state.grade}-${i}`]!=='physics'&&(state.grade===6||topicSubjects[`${state.grade}-${i}`]===state.subject))).filter(({i})=>!state.strongOnly||tasks.some(t=>t.challenge&&t.grade===state.grade&&t.topic===i)).filter(({t,i})=>!state.query||t[0].toLowerCase().includes(state.query)||tasks.some(task=>task.grade===state.grade&&task.topic===i&&matches(task)));
$('#topicCount').textContent=`Тем: ${visibleTopics.length} · Задач: ${tasks.filter(t=>t.grade===state.grade&&subjectMatches(t)&&matches(t)&&(!state.strongOnly||t.challenge)).length}`;
$('#topics').innerHTML=visibleTopics.map(({t,i},index)=>`<article class="topic ${state.topic===i?'active':''}" style="--order:${index}"><div class="topic-topline"><span class="topic-symbol">${t[2]}</span><span class="topic-index">${String(index+1).padStart(2,'0')}</span></div><h3>${t[0]}</h3><p>${t[1]}</p><div class="topic-actions"><button data-lesson="${state.grade}-${i}">Изучить тему <span>↗</span></button><button data-topic="${i}" aria-pressed="${state.topic===i}">Задачи (${tasks.filter(task=>task.grade===state.grade&&task.topic===i).length})</button></div></article>`).join('');
$('#challengeMode').setAttribute('aria-pressed',String(state.strongOnly));$('#challengeMode').innerHTML=state.strongOnly?'Вернуться ко всем задачам ↗':'Сложная подборка ↗';$('.study-ribbon').hidden=state.view!=='catalog';const list=pool();$('#taskCount').textContent=`(${list.length})`;
$('#tasks').innerHTML=list.length?list.slice(0,visibleTaskLimit).map(card).join('')+(list.length>visibleTaskLimit?`<button class="load-more" id="loadMoreTasks">Показать ещё ${Math.min(24,list.length-visibleTaskLimit)} <span>Показано ${visibleTaskLimit} из ${list.length}</span></button>`:''):`<div class="empty"><h3>${state.view==='favorites'&&!saved.length?'Здесь будет твоя коллекция':'Пока ничего не нашлось'}</h3><p>${state.view==='favorites'&&!saved.length?'Нажми на значок рядом с задачей, чтобы сохранить её.':'Попробуй другой уровень или измени поисковый запрос.'}</p><button class="primary" id="resetFilters">${state.view==='favorites'&&!saved.length?'Открыть каталог':'Сбросить фильтры'} ↗</button></div>`;
document.querySelectorAll('[data-level]').forEach(b=>{b.classList.toggle('selected',+b.dataset.level===state.level);b.setAttribute('aria-pressed',String(+b.dataset.level===state.level))});$('#clearTopic').hidden=state.topic===null;
if(state.view==='progress')renderProgress();
if(navigationChanged&&motionAllowed()){for(const el of document.querySelectorAll('.topic,.task-card'))el.getAnimations?.().forEach(a=>a.cancel());for(const [i,el] of [...document.querySelectorAll('.topic,.task-card')].slice(0,8).entries()){el.animate?.([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:280,delay:Math.min(i,3)*30,easing:'cubic-bezier(.2,.7,.2,1)',fill:'backwards'})}}
}
function renderProgress(){const collection=domainTasks(),count=collection.filter(t=>solved.includes(t.id)).length,drafts=Object.entries(workbook).filter(([id])=>collection.some(t=>t.id===id)).map(([,w])=>w).filter(w=>w.steps?.some(s=>s.trim())||w.strokes?.length).length;$('#progress-content').innerHTML=`<div class="stats"><div class="stat"><strong>${count}</strong><span>верных ответов из ${collection.length}</span></div><div class="stat"><strong>${drafts}</strong><span>черновиков в мастерской</span></div><div class="stat"><strong>${Math.round(count/collection.length*100)}%</strong><span>коллекции пройдено</span></div></div><h3>Прогресс по классам</h3>${(state.domain==='physics'?physicsGrades:supportedGrades).map(g=>{const total=collection.filter(t=>t.grade===g).length,n=collection.filter(t=>t.grade===g&&solved.includes(t.id)).length;return `<div class="progress-row"><span>${g} класс</span><progress value="${n}" max="${total}" aria-label="Верных ответов ${n} из ${total} в ${g} классе"></progress><small>${n} / ${total}</small><button class="text-button" data-goto="${g}">Перейти ↗</button></div>`}).join('')}<p class="small" style="margin-top:18px;color:#87917d">Прогресс и черновики сохраняются в этом браузере. Проверяется конечный ответ; ход решения ты можешь сравнить с разбором самостоятельно.</p>`}
function setView(view){state.view=view;state.strongOnly=false;state.topic=null;state.section='all';state.query='';$('#search').value='';render()}
function toggleSave(id){if(saved.includes(id)){saved=saved.filter(v=>v!==id);toast('Задача удалена из избранного')}else{saved.push(id);toast('Задача добавлена в избранное')}persist();render();if(activeTask?.id===id)updateWorkspaceSave()}
function parseAnswer(raw){const str=raw.trim().replace(/\s+/g,'').replace(',','.').replaceAll('−','-');if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(str))return Number(str);const m=str.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\/([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);if(m&&Number(m[2])!==0)return Number(m[1])/Number(m[2]);return NaN}
function lessonHTML(key,compact=false){const l=lessons[key];if(!l)return '<p>Объяснение не найдено.</p>';const [g,i]=key.split('-').map(Number);return `<div class="lesson-content ${compact?'compact':''}"><div class="eyebrow muted">${g} КЛАСС · МИНИ-УРОК</div><h2>${curriculum[g][i][0]}</h2><p class="lesson-intro">${l.intro}</p>${geometryHTML(l.diagram)}${physicsLessonDemo(l)}${deepLessonHTML(key)}<section class="rule-box"><h3>Что нужно запомнить</h3><ul>${l.rules.map(r=>`<li>${r}</li>`).join('')}</ul></section><section class="example-box"><div class="eyebrow">РАЗБЕРЁМ НА ПРИМЕРЕ</div><h3>${l.example}</h3><ol class="numbered-steps">${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><aside class="mistake-box"><b>Ловушка, которую можно обойти</b><p>${l.mistake}</p></aside>${conceptualHTML(key)}<section class="quick-check"><div class="eyebrow">ПРОВЕРЬ, ЧТО ПОНЯЛ</div><p>${l.check}${l.physics?` <span class="physics-unit-note">Ответ в ${esc(l.unit)}.</span>`:''}</p><form class="quick-form" data-check-key="${key}"><input aria-label="Ответ на самопроверку" placeholder="Твой ответ" required autocomplete="off"><button class="primary">Проверить</button><div class="quick-feedback" role="status"></div></form></section>${compact?'':`<button class="primary lesson-practice" data-practice="${key}">Перейти к задачам ↗</button>`}</div>`}
function openLesson(key){$('#lessonBody').innerHTML=lessonHTML(key);$('#lessonBody h2').id='lessonTitle';$('#lessonDialog').setAttribute('aria-labelledby','lessonTitle');$('#lessonDialog').showModal()}
let activeTask=null,boardObserver=null,workTab='steps';
function draftFor(id){let w=workbook[id];if(!w||typeof w!=='object'||!Array.isArray(w.steps)||!Array.isArray(w.strokes)){w=workbook[id]={steps:[''],strokes:[],attempts:0,hintCount:0,revealed:false,answer:''}}return w}
function updateWorkspaceSave(){const b=$('#workspaceSave');if(!b||!activeTask)return;b.textContent=saved.includes(activeTask.id)?'◆ В избранном':'♧ Сохранить';b.setAttribute('aria-pressed',String(saved.includes(activeTask.id)))}
function openTask(id){const t=tasks.find(t=>t.id===id);if(!t)return;activeTask=t;workTab='steps';boardObserver?.disconnect();const w=draftFor(id);$('#modalBody').innerHTML=`<div class="workspace-top"><div><div class="eyebrow">МАСТЕРСКАЯ РЕШЕНИЙ</div><span>${t.grade} класс <i>/</i> ${t.topicName}</span></div><button id="workspaceSave" data-save="${t.id}"></button></div><div class="workspace-grid"><section class="problem-pane"><div class="problem-tags"><span class="level-pill ${['green','amber','purple'][t.level]}">${levels[t.level]}</span><span>${t.goal}</span></div><h2 id="workspaceTitle" class="modal-title">${t.title}</h2><p class="question">${t.question}</p>${t.domain==='physics'?`<div class="physics-condition"><b>Физическая модель</b><p>Выпиши данные, переведи единицы, выбери закон. Ответ проверяется с допуском 0,1% в единице ${esc(t.unit)}.</p></div>`:''}${taskApproach(t)}<form id="answerForm"><label class="answer-label" for="answer">Конечный ответ <span>· ${Array.isArray(t.answer)?'координаты через ;':'число или дробь'}</span></label><div class="answer-row"><input id="answer" name="answer" autocomplete="off" value="${esc(w.answer||'')}" placeholder="${Array.isArray(t.answer)?'(x;y) или (x;y;z)':'Например, 5 или 1/2'}" required aria-describedby="feedback">${t.domain==='physics'?`<select id="answerUnit" aria-label="Единица ответа">${(physicsUnitOptions[t.unit]||[[t.unit,1]]).map(([u,f])=>`<option value="${f}" ${w.answerUnit===u?'selected':''}>${esc(u)}</option>`).join('')}</select>`:''}<button class="primary" type="submit">Проверить ↗</button></div><div class="feedback" id="feedback" role="status"></div><p class="input-note">${t.domain==='physics'?'Вводи число или 1e-3; единицу выбери справа. Допуск 0,1%.':Array.isArray(t.answer)?'Координаты: (6;−8) или (0;3;7). Дроби и десятичная запятая допустимы внутри координат.':'Дроби: 3/4. Десятичные: 0,75.'} Ctrl / ⌘ + Enter — проверить.</p></form><div id="taskStatus" class="task-status">${solved.includes(t.id)?'✓ Ранее получен верный ответ':`Попыток: ${w.attempts||0}`}</div><section class="hint-section"><button class="hint-button" id="getHint">☼ Подсказка <span id="hintCount"></span></button><div id="hints" class="hints"></div></section><details class="details solution-details" id="solutionDetails"><summary>Разобрать решение по шагам</summary>${solutionMarkup(t)}</details><button class="next-task" id="nextTask">Следующая задача <span>→</span></button></section><section class="work-pane"><div class="work-tabs" role="tablist" aria-label="Инструменты решения"><button role="tab" id="tab-steps" aria-controls="panel-steps" aria-selected="true" tabindex="0" data-work-tab="steps">01 Черновик</button><button role="tab" id="tab-board" aria-controls="panel-board" aria-selected="false" tabindex="-1" data-work-tab="board">02 Доска</button><button role="tab" id="tab-theory" aria-controls="panel-theory" aria-selected="false" tabindex="-1" data-work-tab="theory">03 Теория</button></div><div id="panel-steps" role="tabpanel" aria-labelledby="tab-steps" class="work-panel"><div class="scratch-head"><h3>Твоя логика важнее ответа</h3><p>Запиши план, вычисления и проверку. Можно добавлять шаги и возвращаться к ним позже.</p></div><div id="draftSteps"></div><button class="add-step" id="addStep">+ Добавить шаг</button><div class="draft-tools"><span id="saveStatus">Сохраняется в этом браузере</span><button id="exportSolution">Скачать решение ↓</button></div></div><div id="panel-board" role="tabpanel" aria-labelledby="tab-board" class="work-panel" hidden><div class="board-toolbar"><div class="board-colors" aria-label="Цвет пера"><button class="pen-color active" data-pen="#263e32" style="--pen:#263e32" aria-label="Зелёное перо" aria-pressed="true"></button><button class="pen-color" data-pen="#bb6549" style="--pen:#bb6549" aria-label="Терракотовое перо" aria-pressed="false"></button><button class="pen-color" data-pen="#746293" style="--pen:#746293" aria-label="Фиолетовое перо" aria-pressed="false"></button></div><button id="undoStroke" title="Удалить последний штрих">↶ Отменить</button><button id="clearBoard">Очистить</button></div><canvas id="board" aria-label="Доска для записей мышью, пальцем или стилусом. Текстовая альтернатива во вкладке Черновик.">Используй вкладку Черновик для текстового решения.</canvas><p class="board-note">Рисуй мышью, пальцем или стилусом. Доска сохраняется автоматически.</p></div><div id="panel-theory" role="tabpanel" aria-labelledby="tab-theory" class="work-panel theory-panel" hidden>${lessonHTML(`${t.grade}-${t.topic}`,true)}</div></section></div>`;updateWorkspaceSave();renderDraftSteps();renderHints();$('#answerForm').addEventListener('submit',checkAnswer);if($('#answerUnit'))$('#answerUnit').addEventListener('change',()=>{draftFor(activeTask.id).answerUnit=$('#answerUnit').selectedOptions[0].textContent;queueSave()});$('#answer').addEventListener('input',()=>{draftFor(activeTask.id).answer=$('#answer').value;queueSave()});$('#solutionDetails').addEventListener('toggle',()=>{if($('#solutionDetails').open){draftFor(activeTask.id).revealed=true;queueSave()}});if(!$('#taskDialog').open)$('#taskDialog').showModal();$('.problem-pane').scrollTop=0;$('.work-pane').scrollTop=0;if(!window.matchMedia?.('(pointer: coarse)').matches)$('#answer').focus({preventScroll:true})}
let saveTimer;
function queueSave(){if($('#saveStatus'))$('#saveStatus').textContent='Сохраняем…';clearTimeout(saveTimer);saveTimer=setTimeout(saveWork,350)}
function renderDraftSteps(){const w=draftFor(activeTask.id);$('#draftSteps').innerHTML=w.steps.map((value,i)=>`<div class="draft-step"><div class="draft-step-head"><label for="step-${i}"><span>${String(i+1).padStart(2,'0')}</span>${i===0?'С чего начнём?':'Продолжение решения'}</label><button type="button" data-remove-step="${i}" aria-label="Удалить шаг ${i+1}" ${w.steps.length===1?'disabled':''}>×</button></div><textarea id="step-${i}" data-step-index="${i}" rows="3" placeholder="${i===0?(activeTask.domain==='physics'?'Дано: … Найти: … Перевод в СИ: … Физический закон: …':'Что известно? Что нужно найти? Какая идея поможет?'):'Запиши преобразование, вычисление или вывод…'}">${esc(value)}</textarea></div>`).join('')}
function renderHints(){const t=activeTask,w=draftFor(t.id),n=w.hintCount||0;$('#hints').innerHTML=t.hints.slice(0,n).map((h,i)=>`<div class="hint-item"><b>Подсказка ${i+1}</b><p>${h}</p></div>`).join('');$('#hintCount').textContent=`${Math.min(n,t.hints.length)} / ${t.hints.length}`;$('#getHint').disabled=n>=t.hints.length}
function checkAnswer(e){e.preventDefault();if(!activeTask)return;const n=Array.isArray(activeTask.answer)?parseVector($('#answer').value):activeTask.domain==='physics'?physicsNumber($('#answer').value)*Number($('#answerUnit').value):parseAnswer($('#answer').value),f=$('#feedback'),w=draftFor(activeTask.id);w.answer=$('#answer').value;if(activeTask.domain==='physics')w.answerUnit=$('#answerUnit').selectedOptions[0].textContent;if(Array.isArray(activeTask.answer)?!n||n.length!==activeTask.answer.length:!Number.isFinite(n)){f.className='feedback error';f.textContent=Array.isArray(activeTask.answer)?'Введи '+activeTask.answer.length+' координаты через точку с запятой: (6;−8) или (0;3;7).':'Введи число или дробь, например 0,5 или 1/2.';return}w.attempts=(w.attempts||0)+1;if(Array.isArray(activeTask.answer)?n.every((v,i)=>Math.abs(v-activeTask.answer[i])<=1e-5):activeTask.domain==='physics'?physicsAccept(n,activeTask.answer):Math.abs(n-activeTask.answer)<=1e-5){f.className='feedback success';f.textContent=w.revealed?'Ответ верный. Теперь попробуй объяснить каждый шаг без подсказки.':'Верно! Сохрани ход мысли и попробуй следующую задачу.';if(!solved.includes(activeTask.id)){solved.push(activeTask.id);persist();render();celebrate()}$('#taskStatus').textContent='✓ Верный ответ · Попыток: '+w.attempts}else{f.className='feedback error';const diagnosis=Object.entries(activeTask.wrong||{}).find(([value])=>Math.abs(n-Number(value))<=Math.max(1e-5,Math.abs(Number(value))*.001));f.textContent=diagnosis?diagnosis[1]:w.attempts<2?'Пока не сходится. Проверь знаки, единицы и порядок действий.':'Пока не сходится. Сверь план с теорией или открой подсказку.';$('#taskStatus').textContent='Попыток: '+w.attempts;if(motionAllowed())f.animate?.([{transform:'translateX(0)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:220})}saveWork()}
function celebrate(){if(!motionAllowed())return;const host=document.createElement('div');host.className='celebration';host.setAttribute('aria-hidden','true');for(let i=0;i<14;i++){const p=document.createElement('i');p.style.setProperty('--dx',`${(Math.random()-.5)*300}px`);p.style.setProperty('--dy',`${-80-Math.random()*150}px`);p.style.setProperty('--spin',`${Math.random()*600}deg`);p.style.background=['#dcb165','#bb6549','#729067'][i%3];host.append(p)}$('#feedback').append(host);setTimeout(()=>host.remove(),1100)}
function selectWorkTab(tab){workTab=tab;document.querySelectorAll('[data-work-tab]').forEach(b=>{const active=b.dataset.workTab===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});for(const id of ['steps','board','theory'])$('#panel-'+id).hidden=id!==tab;if(tab==='board')setupBoard()}
let pen='#263e32',drawing=null,boardBound=null,boardFrame=0;
function scheduleBoard(){if(boardFrame)return;boardFrame=requestAnimationFrame(()=>{boardFrame=0;drawBoard()})}
function drawBoard(){const canvas=$('#board');if(!canvas||workTab!=='board'||!activeTask)return;const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.lineCap='round';ctx.lineJoin='round';const strokes=[...draftFor(activeTask.id).strokes,...(drawing?[drawing]:[])];for(const s of strokes){if(!s.points?.length)continue;ctx.strokeStyle=s.color;ctx.lineWidth=2.3;ctx.beginPath();ctx.moveTo(s.points[0][0]*rect.width,s.points[0][1]*rect.height);if(s.points.length===1)ctx.lineTo(s.points[0][0]*rect.width+.1,s.points[0][1]*rect.height);for(const [x,y] of s.points.slice(1))ctx.lineTo(x*rect.width,y*rect.height);ctx.stroke()}}
function setupBoard(){const canvas=$('#board');drawBoard();if(boardBound===canvas)return;boardBound=canvas;drawing=null;const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]};canvas.addEventListener('pointerdown',e=>{if(e.button!==0||drawing)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drawing={color:pen,points:[point(e)]};drawBoard()});canvas.addEventListener('pointermove',e=>{if(!drawing||!canvas.hasPointerCapture(e.pointerId))return;const p=point(e),last=drawing.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])<.001)return;drawing.points.push(p);scheduleBoard()});const end=()=>{if(!drawing)return;draftFor(activeTask.id).strokes.push(drawing);drawing=null;saveWork();drawBoard()};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);if(typeof ResizeObserver!=='undefined'){boardObserver?.disconnect();boardObserver=new ResizeObserver(drawBoard);boardObserver.observe(canvas)}}
function exportSolution(){const t=activeTask,w=draftFor(t.id);const content=`МАТКЛУБ · ${t.grade} класс · ${t.topicName}\n${t.title}\n\nУСЛОВИЕ\n${t.question}\n\nМОЁ РЕШЕНИЕ\n${w.steps.map((s,i)=>`${i+1}. ${s||'(шаг не заполнен)'}`).join('\n\n')}\n\nОТВЕТ: ${w.answer||'не записан'}${t.domain==='physics'?' '+(w.answerUnit||t.unit):''}\nСТАТУС: ${solved.includes(t.id)?'Получен верный ответ':'Ответ пока не подтверждён'}\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`matclub-${t.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Текст решения скачан. Рисунок остаётся на доске.')}
function nextTask(){const t=activeTask;let list=tasks.filter(q=>q.grade===t.grade&&q.topic===t.topic);const index=list.findIndex(q=>q.id===t.id);const next=list.slice(index+1).find(q=>!solved.includes(q.id))||list.find(q=>q.id!==t.id&&!solved.includes(q.id))||list[(index+1)%list.length];saveWork();openTask(next.id)}
document.addEventListener('input',e=>{if(e.target.dataset.stepIndex!==undefined&&activeTask){draftFor(activeTask.id).steps[+e.target.dataset.stepIndex]=e.target.value;queueSave()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('.quick-form'))return;e.preventDefault();const l=lessons[form.dataset.checkKey],value=l.physics?physicsNumber(form.querySelector('input').value):parseAnswer(form.querySelector('input').value),feedback=form.querySelector('.quick-feedback');const good=Number.isFinite(value)&&(l.physics?physicsAccept(value,l.answer):Math.abs(value-l.answer)<=1e-5);feedback.textContent=good?'Верно! Можно переходить к практике.':'Попробуй ещё раз: вернись к правилу и примеру выше.';feedback.className='quick-feedback '+(good?'success':'error')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.id==='challengeMode'){state.query='';$('#search').value='';state.strongOnly=!state.strongOnly;state.topic=null;state.level=state.strongOnly?2:-1;render();$('#tasks').scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'start'});return}if(b.id==='loadMoreTasks'){visibleTaskLimit+=24;render();return}if(b.dataset.domain){state.domain=b.dataset.domain;state.section='all';storeLocal('matclub-domain',state.domain);setView('catalog');return}if(b.dataset.view){setView(b.dataset.view);window.scrollTo({top:0,behavior:motionAllowed()?'smooth':'auto'});return}if(b.dataset.subject){state.subject=b.dataset.subject;state.topic=null;state.level=-1;render();return}if(b.dataset.grade){state.grade=+b.dataset.grade;state.topic=null;state.section='all';render();return}if(b.dataset.lesson){openLesson(b.dataset.lesson);return}if(b.dataset.practice){const [g,i]=b.dataset.practice.split('-').map(Number);state.grade=g;state.domain=topicSubjects[`${g}-${i}`]==='physics'?'physics':'math';state.subject=topicSubjects[`${g}-${i}`];setView('catalog');state.topic=i;state.level=-1;render();$('#lessonDialog').close();$('#tasks').scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'start'});return}if(b.dataset.topic!==undefined){state.topic=state.topic===+b.dataset.topic?null:+b.dataset.topic;render();return}if(b.dataset.level!==undefined){state.level=+b.dataset.level;render();return}if(b.dataset.open){openTask(b.dataset.open);return}if(b.dataset.save){toggleSave(b.dataset.save);return}if(b.dataset.goto){state.grade=+b.dataset.goto;setView('catalog');return}if(b.dataset.workTab){selectWorkTab(b.dataset.workTab);return}if(b.dataset.pen){pen=b.dataset.pen;document.querySelectorAll('[data-pen]').forEach(p=>{p.classList.toggle('active',p===b);p.setAttribute('aria-pressed',String(p===b))});return}if(b.dataset.removeStep!==undefined){const w=draftFor(activeTask.id);if(w.steps.length>1){w.steps.splice(+b.dataset.removeStep,1);renderDraftSteps();saveWork()}return}if(b.classList.contains('close'))b.closest('dialog').close();
if(b.id==='getHint'){draftFor(activeTask.id).hintCount++;renderHints();saveWork()}if(b.id==='addStep'){const w=draftFor(activeTask.id);w.steps.push('');renderDraftSteps();$('#step-'+(w.steps.length-1)).focus();saveWork()}if(b.id==='exportSolution')exportSolution();if(b.id==='nextTask')nextTask();if(b.id==='undoStroke'){draftFor(activeTask.id).strokes.pop();drawBoard();saveWork()}if(b.id==='clearBoard'){draftFor(activeTask.id).strokes=[];drawing=null;drawBoard();saveWork();toast('Доска очищена')}if(b.id==='resetFilters'){state.strongOnly=false;state.topic=null;state.level=-1;state.query='';$('#search').value='';if(state.view==='favorites'&&!saved.length)state.view='catalog';render()}});
document.addEventListener('keydown',e=>{if($('#taskDialog').open&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('#answerForm').requestSubmit()}const tab=e.target.closest('[data-work-tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['steps','board','theory'],i=tabs.indexOf(tab.dataset.workTab);const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectWorkTab(tabs[n]);$('#tab-'+tabs[n]).focus()}});
$('#search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();visibleTaskLimit=24;if(state.view==='progress')state.view='catalog';render()});$('#clearTopic').onclick=()=>{state.topic=null;render()};
$('#random').onclick=()=>{$('#challengeMode').setAttribute('aria-pressed',String(state.strongOnly));$('#challengeMode').innerHTML=state.strongOnly?'Вернуться ко всем задачам ↗':'Сложная подборка ↗';$('.study-ribbon').hidden=state.view!=='catalog';const list=pool();if(!list.length){toast('Для этих фильтров пока нет задач');return}openTask(list[Math.floor(Math.random()*list.length)].id)};
$('#explore').onclick=()=>{setView('catalog');state.level=2;render();$('#tasks').scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'center'})};$('#start').onclick=()=>{setView('catalog');$('#catalog').scrollIntoView({behavior:motionAllowed()?'smooth':'auto'})};$('.brand').onclick=e=>{e.preventDefault();setView('catalog');window.scrollTo({top:0,behavior:motionAllowed()?'smooth':'auto'})};for(const id of ['about','help'])$('#'+id).onclick=()=>$('#aboutDialog').showModal();$('#gotIt').onclick=()=>$('#aboutDialog').close();
$('#taskDialog').addEventListener('close',()=>{clearTimeout(saveTimer);saveWork();boardObserver?.disconnect();drawing=null;render()});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);saveWork()});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
render();

$('#physicsSection').addEventListener('change',e=>{state.section=e.target.value;state.topic=null;render()});
